+    function computeCycleTimeByStage() {
+      const stageKeys = ['pull', 'story', 'code', 'test', 'code_review', 'ac_check', 'deploy'];
+      fetch('/sdlc_pipeline.json')
+        .then(r => r.json())
+        .then(data => {
+          const items = Array.isArray(data) ? data : (data.items || []);
+          const sprintMap = {};
+          items.forEach(item => {
+            const sn = item.sprint_number;
+            if (sn == null) return;
+            if (!sprintMap[sn]) sprintMap[sn] = [];
+            sprintMap[sn].push(item);
+          });
+          const sprints = Object.keys(sprintMap).map(Number).sort((a, b) => b - a).slice(0, 5);
+          const tbody = document.getElementById('cycle-time-tbody');
+          if (!tbody) return;
+          tbody.innerHTML = sprints.map(sn => {
+            const sprintItems = sprintMap[sn];
+            const cells = stageKeys.map(key => {
+              const vals = sprintItems
+                .map(it => it.stage_times && it.stage_times[key])
+                .filter(v => typeof v === 'number' && !isNaN(v));
+              if (vals.length === 0) return '\u2014';
+              const mean = vals.reduce((a, b) => a + b, 0) / vals.length;
+              return mean.toFixed(1) + 's';
+            });
+            return `<tr><td>Sprint ${escHtml(String(sn))}</td>${cells.map(c => `<td>${escHtml(c)}</td>`).join('')}</tr>`;
+          }).join('');
+        })
+        .catch(() => {});
+    }
+    computeCycleTimeByStage();
